"use client";

import * as React from "react";
import { RadioGroup as RadioGroupPrimitive } from "@base-ui/react/radio-group";
import { Radio as RadioPrimitive } from "@base-ui/react/radio";
import { motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";
import { focusRing, panelSpring, selectedOption, optionTrack } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** What an option needs from its group to draw the sliding panel. */
interface RadioGroupState {
  panelId: string;
  reduceMotion: boolean;
}

const RadioGroupContext = React.createContext<RadioGroupState | null>(null);

/** Props for the RadioGroup, where `well` sets the options in one lilac option track with a sliding chosen-option tint. */
interface RadioGroupProps extends WithClassName<RadioGroupPrimitive.Props> {
  variant?: "default" | "well";
}

/** Mallow RadioGroup: plain radios in a column by default, or options in a lilac track whose violet-ringed tint slides to the choice. */
function RadioGroup({ className, variant = "default", ...props }: RadioGroupProps) {
  const panelId = React.useId();
  const reduceMotion = useReducedMotion() ?? false;

  return (
    <RadioGroupContext.Provider value={{ panelId, reduceMotion }}>
      <RadioGroupPrimitive
        data-slot="radio-group"
        data-variant={variant}
        className={cn(
          variant === "well"
            ? cn(optionTrack, "isolate grid auto-cols-fr gap-1 rounded-2xl p-1 sm:grid-flow-col")
            : "grid gap-3",
          className,
        )}
        {...props}
      />
    </RadioGroupContext.Provider>
  );
}
RadioGroup.displayName = "RadioGroup";

// The round mark: an ink outline when empty, the solid violet finish when chosen.
const radioMark =
  "relative grid size-5 shrink-0 place-items-center rounded-full border-2 border-foreground/50 " +
  "transition-[background-color,border-color,box-shadow] duration-fast ease-(--ease-out)";

const radioMarkChecked = "border-transparent bg-(image:--violet-face) shadow-(--violet-edge)";

/** One round radio that takes the solid violet finish with a pale lilac centre dot when chosen. */
function RadioGroupItem({ className, ...props }: WithClassName<RadioPrimitive.Root.Props>) {
  return (
    <RadioPrimitive.Root
      data-slot="radio-group-item"
      className={cn(
        radioMark,
        "aspect-square hover:border-foreground/70",
        "data-[checked]:border-transparent data-[checked]:bg-(image:--violet-face) data-[checked]:shadow-(--violet-edge)",
        focusRing,
        "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
        className,
      )}
      {...props}
    >
      <RadioPrimitive.Indicator data-slot="radio-group-indicator" className="size-full grid place-items-center">
        <span className="size-1.75 rounded-full bg-primary-foreground" />
      </RadioPrimitive.Indicator>
    </RadioPrimitive.Root>
  );
}
RadioGroupItem.displayName = "RadioGroupItem";

/** Props for one option inside a `well` group: a label, an optional icon and any content below. */
interface RadioGroupOptionProps extends Omit<WithClassName<RadioPrimitive.Root.Props>, "children"> {
  label: React.ReactNode;
  icon?: React.ReactNode;
  children?: React.ReactNode;
}

/** One option inside a `well` group, with the chosen-option tint sliding under it when chosen. */
function RadioGroupOption({ className, label, icon, children, ...props }: RadioGroupOptionProps) {
  const group = React.useContext(RadioGroupContext);

  return (
    <RadioPrimitive.Root
      data-slot="radio-group-option"
      className={cn(
        "group/option relative block rounded-xl px-4.5 pt-4 pb-4.5 text-left text-foreground",
        focusRing,
        "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
        className,
      )}
      {...props}
      render={(radioProps, state) => (
        <span {...radioProps}>
          {state.checked && (
            <motion.span
              layoutId={`${group?.panelId}-panel`}
              aria-hidden="true"
              data-slot="radio-group-panel"
              className={cn(selectedOption, "absolute inset-0 z-0 rounded-xl")}
              transition={group?.reduceMotion ? { duration: 0 } : panelSpring}
            />
          )}
          <span className="relative z-10 grid">
            <span className="flex items-center gap-2.5 text-base font-medium leading-6 [&_svg]:size-5 [&_svg]:shrink-0">
              {icon}
              {label}
              <span
                aria-hidden="true"
                className={cn(
                  radioMark,
                  "ms-auto",
                  state.checked ? radioMarkChecked : "group-hover/option:border-foreground/70",
                )}
              >
                {state.checked && <span className="size-1.75 rounded-full bg-primary-foreground" />}
              </span>
            </span>
            {children}
          </span>
        </span>
      )}
    />
  );
}
RadioGroupOption.displayName = "RadioGroupOption";

export { RadioGroup, RadioGroupItem, RadioGroupOption };
export type { RadioGroupProps, RadioGroupOptionProps };
